func TestEnumProjectBaseEnvironment(t *testing.T) {
	t.Run("NewFromString_Development", func(t *testing.T) {
		t.Parallel()
		val, err := NewProjectBaseEnvironmentFromString("Development")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ProjectBaseEnvironment("Development"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Staging", func(t *testing.T) {
		t.Parallel()
		val, err := NewProjectBaseEnvironmentFromString("Staging")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ProjectBaseEnvironment("Staging"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Production", func(t *testing.T) {
		t.Parallel()
		val, err := NewProjectBaseEnvironmentFromString("Production")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, ProjectBaseEnvironment("Production"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewProjectBaseEnvironmentFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewProjectBaseEnvironmentFromString("Development")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesProject(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &Project{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *Project
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}

